from __future__ import annotations

import secrets

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["owner-dashboard-ui"])

PAGE = r'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>X1 Owner Dashboard</title><style nonce="__NONCE__">
:root{--bg:#090b10;--panel:#111620;--line:#29313d;--text:#f4f6fa;--muted:#95a0b0;--ok:#68d596;--warn:#efbd63;--bad:#ff8383;--accent:#d34747}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 Inter,system-ui,Arial,sans-serif}.top{position:sticky;top:0;z-index:4;padding:11px max(12px,calc((100% - 1180px)/2));background:#090b10f5;border-bottom:1px solid var(--line);display:flex;gap:8px;align-items:center;flex-wrap:wrap}.top a,.top button{border:1px solid var(--line);border-radius:9px;padding:8px 10px;color:var(--text);background:#151a23;text-decoration:none;cursor:pointer}.brand{font-weight:900}.grow{flex:1}.wrap{width:min(1180px,100%);margin:auto;padding:16px 12px 60px}.auth{display:flex;gap:8px;align-items:center}.auth input{min-width:280px}.section{margin-top:21px}.section h2{font-size:18px;margin:0 0 8px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.card{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:13px;min-width:0}.label{color:var(--muted);font-size:12px}.value{font-size:25px;font-weight:850;letter-spacing:-.03em;overflow-wrap:anywhere}.sub{font-size:12px;color:var(--muted);margin-top:4px}.ok{color:var(--ok)}.warn{color:var(--warn)}.bad{color:var(--bad)}input,select{padding:9px;border:1px solid var(--line);border-radius:8px;background:#0c1118;color:var(--text)}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid var(--line);padding:8px;text-align:left}th{color:var(--muted);font-weight:600}.status{min-height:22px;color:var(--muted);margin-top:9px}.links{display:flex;gap:8px;flex-wrap:wrap}.links a{border:1px solid var(--line);padding:9px 11px;border-radius:9px;color:var(--text);text-decoration:none;background:#151a23}@media(max-width:900px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.grid{grid-template-columns:1fr}.auth{width:100%;flex-wrap:wrap}.auth input,.auth select,.auth button{width:100%;min-width:0}.top{position:static}}
</style></head><body><header class="top"><div class="brand">X1 · Owner</div><div class="grow"></div><a href="/admin">Control Center</a><a href="/admin/analytics">Analytics</a><a href="/admin/integrations">Integrations</a><a href="/admin/support">Support</a></header><main class="wrap"><section class="card"><div class="auth"><input id="token" type="password" autocomplete="off" placeholder="Admin Bearer token"><select id="days"><option value="7">7 дней</option><option value="30" selected>30 дней</option><option value="90">90 дней</option></select><button id="load">Обновить</button></div><div class="status" id="status">Здесь только агрегаты: prompt и тексты чатов не нужны для бизнес-метрик.</div></section><section class="section"><h2>Деньги и окупаемость</h2><div class="grid" id="finance"></div></section><section class="section"><h2>Пользователи и воронка</h2><div class="grid" id="users"></div></section><section class="section"><h2>Качество и скорость</h2><div class="grid" id="quality"></div></section><section class="section"><h2>Поддержка и инфраструктура продаж</h2><div class="grid" id="ops"></div></section><section class="section"><h2>Платежи по провайдерам</h2><div class="card" id="payments"></div></section><section class="section"><h2>Быстрые действия</h2><div class="links"><a href="/admin/integrations">Настроить SMTP / Метрику / платежи</a><a href="/admin/support">Ответить клиентам</a><a href="/admin/users">Пользователи</a><a href="/admin/capabilities">Capabilities</a><a href="/admin/analytics">Глубокая продуктовая аналитика</a></div></section></main><script nonce="__NONCE__">
const $=id=>document.getElementById(id);$('token').value=sessionStorage.getItem('x1AdminToken')||'';function val(v,suffix=''){if(v===null||v===undefined)return '—';return String(v)+suffix}function pct(v){return v===null||v===undefined?'—':(Number(v)*100).toFixed(1)+'%'}function rub(v){return v===null||v===undefined?'—':Number(v).toLocaleString('ru-RU',{maximumFractionDigits:2})+' ₽'}function ms(v){return v===null||v===undefined?'—':Number(v).toLocaleString('ru-RU')+' мс'}function card(root,label,value,sub='',kind=''){const c=document.createElement('div');c.className='card';const l=document.createElement('div');l.className='label';l.textContent=label;const x=document.createElement('div');x.className='value '+kind;x.textContent=value;const s=document.createElement('div');s.className='sub';s.textContent=sub;c.append(l,x,s);root.append(c)}async function api(path){const t=sessionStorage.getItem('x1AdminToken')||'';if(!t)throw new Error('Введите admin token');const r=await fetch(path,{headers:{Authorization:'Bearer '+t},credentials:'omit'});let d=null;try{d=await r.json()}catch{}if(!r.ok)throw new Error(typeof d?.detail==='string'?d.detail:'HTTP '+r.status);return d}function clear(id){$(id).replaceChildren()}function providerTable(data){const root=$('payments');root.replaceChildren();const t=document.createElement('table'),head=document.createElement('tr');for(const h of ['Провайдер','Записей','Оплаты','Возвраты']){const th=document.createElement('th');th.textContent=h;head.append(th)}t.append(head);for(const [name,row] of Object.entries(data||{})){const tr=document.createElement('tr');for(const x of [name,row.records,rub(Number(row.payments_minor||0)/100),rub(Number(row.refunds_minor||0)/100)]){const td=document.createElement('td');td.textContent=String(x);tr.append(td)}t.append(tr)}if(t.rows.length===1){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=4;td.textContent='Подтверждённых платежей за период пока нет.';tr.append(td);t.append(tr)}root.append(t)}async function load(){sessionStorage.setItem('x1AdminToken',$('token').value.trim());$('status').textContent='Загрузка…';try{const d=await api('/v1/admin/owner-dashboard?days='+encodeURIComponent($('days').value)),f=d.finance||{},a=d.accounts||{},q=d.quality||{},p=d.performance||{},s=d.support||{},i=d.integrations||{};for(const id of ['finance','users','quality','ops'])clear(id);card($('finance'),'MRR',rub(f.mrr_rub),'активные подписки');card($('finance'),'После аренды сервера',rub(f.mrr_after_server_rub),'без эквайринга, налогов и маркетинга',Number(f.mrr_after_server_rub||0)>=0?'ok':'warn');card($('finance'),'ARPPU',rub(f.arppu_rub),'средний MRR на платящего');card($('finance'),'Checkout → paid',pct(f.checkout_conversion),val(f.checkout_paid)+' из '+val(f.checkout_created));card($('finance'),'Выручка за окно',rub(f.recognized_payment_rub_window),'подтверждённые payment records');card($('finance'),'Возвраты за окно',rub(f.refund_rub_window));card($('finance'),'Платящих',val(f.active_paid_users));card($('finance'),'Break-even users',val(f.break_even_paid_users_at_current_arppu),'при текущем ARPPU');card($('users'),'Всего аккаунтов',val(a.total_users));card($('users'),'Новых за окно',val(a.new_users));card($('users'),'Активны 24ч',val(a.active_24h));card($('users'),'Активны 7д',val(a.active_7d));card($('users'),'Activation',pct(a.activation_rate));card($('users'),'D1 retention',pct(a.d1_retention));card($('users'),'D7 retention',pct(a.d7_retention));card($('quality'),'Успешные запросы',pct(q.request_success_rate));card($('quality'),'Frustration',pct(q.frustration_rate),'чем ниже, тем лучше',Number(q.frustration_rate||0)>.15?'warn':'');card($('quality'),'Task success',pct(q.task_success_rate));card($('quality'),'Compute waste',pct(q.compute_waste_rate),'чем ниже, тем лучше',Number(q.compute_waste_rate||0)>.2?'warn':'');card($('quality'),'p95 ответа',ms(p.p95_duration_ms));card($('quality'),'p95 очереди',ms(p.p95_queue_ms));card($('quality'),'CPU sec / success',val(p.cpu_seconds_per_success));card($('quality'),'Inference minutes',val(p.inference_minutes));card($('ops'),'Открытых тикетов',val(s.open),'ждут работы');card($('ops'),'Ждут админа',val(s.waiting_admin),'ответьте в Support',Number(s.waiting_admin||0)>0?'warn':'');card($('ops'),'SMTP',i.smtp?.ready?'Готов':'Не готов','регистрация / recovery / уведомления',i.smtp?.ready?'ok':'bad');card($('ops'),'Яндекс Метрика',i.metrika?.ready?'Готова':'Не готова',i.metrika?.counter_id||'counter не задан',i.metrika?.ready?'ok':'warn');card($('ops'),'ЮKassa',i.payments?.yookassa?.ready?'Готова':'Не готова','server-verified webhook',i.payments?.yookassa?.ready?'ok':'warn');card($('ops'),'ЮMoney',i.payments?.yoomoney?.ready?'Готов':'Не готов','HMAC notifications',i.payments?.yoomoney?.ready?'ok':'warn');providerTable(f.payments_by_provider);$('status').textContent='Обновлено '+new Date(d.generated_at).toLocaleString('ru-RU')}catch(e){$('status').textContent=e.message}}$('load').onclick=load;$('days').onchange=()=>{if(sessionStorage.getItem('x1AdminToken'))load()};if(sessionStorage.getItem('x1AdminToken'))load();
</script></body></html>'''


@router.get("/admin/owner", response_class=HTMLResponse, include_in_schema=False)
def owner_dashboard_page() -> HTMLResponse:
    nonce = secrets.token_urlsafe(18)
    response = HTMLResponse(PAGE.replace("__NONCE__", nonce))
    response.headers.update({
        "Content-Security-Policy": f"default-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'; style-src 'nonce-{nonce}'; script-src 'nonce-{nonce}'; connect-src 'self'",
        "Cache-Control": "no-store",
        "Pragma": "no-cache",
        "Referrer-Policy": "no-referrer",
        "X-Content-Type-Options": "nosniff",
        "X-Frame-Options": "DENY",
    })
    return response
